<script setup lang="ts">
import {useUnsavedDraft} from '../../router/useUnsavedDraft'
import PageState from '../../components/PageState.vue'
import {computed,onUnmounted,ref,watch} from 'vue'
import {useAuthStore} from '../../stores/auth'
import {ApiError} from '../../api/auth'
import * as api from '../../api/positions'
import {searchInstruments,type Instrument} from '../../api/market'
import {publishedModels,supportsFiveDayPrediction,type PublishedModel} from '../../api/predictions'
import PositionEditor from './PositionEditor.vue'
import PortfolioAnalysisPanel from './PortfolioAnalysisPanel.vue'
const auth=useAuthStore(),owner=computed(()=>auth.profile?.userId||'')
const book=ref<api.PositionBook>({bookRevision:'0',items:[]}),instruments=ref<Instrument[]>([]),models=ref<PublishedModel[]>([])
const bookAvailable=ref(false),draftDirty=ref(false)
const discardDraft=useUnsavedDraft(computed(()=>!!owner.value&&draftDirty.value),'持仓草稿')
const loading=ref(false),busy=ref(false),error=ref(''),notice=ref(''),catalogError=ref(''),query=ref(''),editing=ref<api.PositionView|null>(null),removing=ref<api.PositionView|null>(null),conflict=ref(false),editorKey=ref(0)
type Pending={action:'CREATE';input:api.CreatePosition}|{action:'UPDATE';id:string;input:api.UpdatePosition}|{action:'DELETE';id:string;input:api.DeletePosition}
const pending=ref<Pending|null>(null),canRetry=ref(false)
let epoch=0,loadSequence=0,searchSequence=0
const disabled=computed(()=>loading.value||busy.value||!!pending.value||conflict.value||!owner.value)
async function load(){const turn=++loadSequence,account=epoch;loading.value=true;bookAvailable.value=false;error.value='';try{const next=await api.listPositions();if(turn!==loadSequence||account!==epoch)return;book.value=next;bookAvailable.value=true;conflict.value=false;if(editing.value){const updated=next.items.find(x=>x.positionId===editing.value?.positionId);if(updated){editing.value=updated;notice.value='已读取新版本，请核对输入后再保存'}else{editing.value=null;editorKey.value++;notice.value='原记录已不存在，请核对当前持仓'}}}catch(e){if(turn===loadSequence&&account===epoch)error.value=(e as Error).message}finally{if(turn===loadSequence&&account===epoch)loading.value=false}}
async function search(){const turn=++searchSequence,account=epoch;catalogError.value='';try{const result=await searchInstruments(query.value);if(turn===searchSequence&&account===epoch)instruments.value=result.items}catch(e){if(turn===searchSequence&&account===epoch)catalogError.value=(e as Error).message}}
async function loadModels(account:number){try{const catalog=await publishedModels();if(account===epoch)models.value=catalog.items}catch{if(account===epoch)models.value=[]}}
function complete(receipt:api.PositionReceipt){pending.value=null;canRetry.value=false;removing.value=null;if(receipt.state==='REJECTED'){error.value=receipt.message;conflict.value=receipt.httpStatus===409;return}notice.value=receipt.action==='DELETE'?'已移除当前持仓。历史估值可继续查看。':receipt.action==='UPDATE'?'已保存持仓修改。历史估值可继续查看。':'持仓操作已保存';draftDirty.value=false;error.value='';editing.value=null;editorKey.value++;void load()}
async function perform(){const current=pending.value,account=epoch;if(!current||busy.value)return;busy.value=true;error.value='';canRetry.value=false;try{const receipt=current.action==='CREATE'?await api.createPosition(current.input):current.action==='UPDATE'?await api.updatePosition(current.id,current.input):await api.deletePosition(current.id,current.input);if(account===epoch)complete(receipt)}catch(e){if(account!==epoch)return;error.value=(e as Error).message;if(e instanceof ApiError&&[400,401,403,404,409,413,422].includes(e.status)){pending.value=null;conflict.value=e.status===409;removing.value=null}else error.value+='。操作结果尚未确认，请先核对原操作。'}finally{if(account===epoch)busy.value=false}}
function save(input:{instrumentId:string;quantity:string;averageCost:string}){if(disabled.value)return;notice.value='';const requestId=crypto.randomUUID();pending.value=editing.value?{action:'UPDATE',id:editing.value.positionId,input:{requestId,expectedRevision:editing.value.revision,quantity:input.quantity,averageCost:input.averageCost}}:{action:'CREATE',input:{requestId,...input}};void perform()}
function edit(item:api.PositionView){if(disabled.value||editing.value?.positionId===item.positionId||!discardDraft())return;editing.value=item;removing.value=null;error.value='';notice.value=''}
function cancelEdit(){if(discardDraft()){editing.value=null;draftDirty.value=false;editorKey.value++}}
function confirmRemoval(){if(!removing.value||disabled.value||!discardDraft())return;pending.value={action:'DELETE',id:removing.value.positionId,input:{requestId:crypto.randomUUID(),expectedRevision:removing.value.revision}};void perform()}
async function recover(){const current=pending.value,account=epoch;if(!current||busy.value)return;busy.value=true;error.value='';try{const result=await api.positionOperation(current.input.requestId);if(account===epoch)complete(result)}catch(e){if(account!==epoch)return;if(e instanceof ApiError&&e.status===404){canRetry.value=true;error.value='尚无已提交回执。如需继续，只能使用原编号重试；原请求可能仍在执行。'}else error.value=(e as Error).message}finally{if(account===epoch)busy.value=false}}
watch(owner,id=>{epoch++;loadSequence++;searchSequence++;bookAvailable.value=false;draftDirty.value=false;book.value={bookRevision:'0',items:[]};editing.value=null;removing.value=null;pending.value=null;canRetry.value=false;conflict.value=false;loading.value=false;busy.value=false;error.value='';notice.value='';catalogError.value='';instruments.value=[];models.value=[];editorKey.value++;if(id){void load();void search();void loadModels(epoch)}},{immediate:true})
onUnmounted(()=>{epoch++;loadSequence++;searchSequence++})
</script>
<template><main class="portfolio-page"><header class="heading"><div><p class="eyebrow">我的资产记录</p><h1>我的持仓</h1><p class="hint">维护本人股票数量与平均成本，按已保存的收盘价生成可追溯估值。</p></div><button :disabled="busy||!!pending||!owner" @click="load">重新读取持仓</button></header><PageState v-if="error" :kind="pending?'pending':'error'" :message="error"/><p v-if="notice" role="status">{{notice}}</p><section v-if="pending" class="panel recovery" aria-label="原操作恢复"><h2>核对未确认的操作</h2><p>当前输入已锁定，不会自动换编号再提交。刷新页面不会保存这些输入，请先核对当前已保存列表。</p><button data-test="position-recover" :disabled="busy" @click="recover">核对原操作</button><button v-if="canRetry" data-test="position-retry" :disabled="busy" @click="perform">使用原编号重试</button></section><p v-if="conflict" role="status">请先重新读取持仓，再核对当前输入和记录版本。</p><section class="panel" aria-label="当前持仓"><div class="heading"><h2>当前持仓<template v-if="bookAvailable"> · {{book.items.length}} 只</template></h2><span v-if="bookAvailable">持仓版本 {{book.bookRevision}}</span><router-link v-if="bookAvailable&&book.items.length" to="/comparisons?source=portfolio">从持仓选股对比</router-link></div><PageState v-if="loading" kind="loading" message="正在读取持仓…"/><PageState v-else-if="bookAvailable&&!book.items.length" kind="empty" message="还没有持仓记录。可以在下方搜索股票并添加。"/><p v-if="!bookAvailable&&!loading&&book.items.length" class="hint small">暂时无法读取当前持仓，以下为上次读取的记录。</p><article v-for="item in book.items" :key="item.positionId" class="position-row"><div><strong>{{item.instrumentId}}</strong><p class="small">记录版本 {{item.revision}}</p></div><div><span class="hint small">持仓股数</span><p>{{item.quantity}} 股</p></div><div><span class="hint small">平均成本（元）</span><p>{{item.averageCost}}</p></div><div class="row-actions"><button data-test="position-edit" :disabled="disabled" @click="edit(item)">编辑</button><button data-test="position-remove" :disabled="disabled" @click="removing=item">移除</button><router-link :to="'/market/'+item.instrumentId">查看分析</router-link><router-link v-if="models.some(model=>supportsFiveDayPrediction(model,item.instrumentId))" :to="'/market/'+item.instrumentId+'/predict'">发起预测</router-link></div></article><div v-if="removing" class="remove-confirm" role="group" aria-label="确认移除持仓"><p>确认移除 {{removing.instrumentId}} 的当前持仓？此操作只更新系统内的持仓记录，已保存估值仍使用当时的记录。</p><button data-test="position-confirm-remove" :disabled="disabled" @click="confirmRemoval">确认移除</button><button :disabled="busy||!!pending" @click="removing=null">取消</button></div></section><section class="panel"><div v-if="!editing" class="stock-search"><label for="position-query">查找已核验股票</label><div class="row-actions"><input id="position-query" v-model="query" :disabled="disabled" placeholder="股票代码或名称"/><button :disabled="disabled" @click="search">查询股票</button></div><p v-if="catalogError" role="status">{{catalogError}}；已有持仓仍可查看、编辑和移除。</p></div><PositionEditor :key="editorKey" :editing="editing" :instruments="instruments" :disabled="disabled" @save="save" @cancel="cancelEdit" @dirty-change="draftDirty=$event"/></section><PortfolioAnalysisPanel :current-book-revision="bookAvailable?book.bookRevision:null"/><p class="hint small">当前为手动记录，不连接券商账户。页面刷新先核对已保存列表，再进行新的修改；不会自动发起交易、预测或AI调用。</p></main></template>
<style scoped>.portfolio-page{max-width:1180px;margin:auto;padding:36px 24px 72px}h1{font-size:30px;margin:0}h2{font-size:20px;margin:0}.heading{display:flex;justify-content:space-between;gap:18px;align-items:center;flex-wrap:wrap}.panel{background:white;border:1px solid var(--border);border-radius:14px;padding:24px;margin:24px 0}.position-row{display:grid;grid-template-columns:1fr .8fr 1fr 1.8fr;gap:18px;padding:20px 0;border-top:1px solid var(--border);margin-top:16px;overflow-wrap:anywhere}.position-row p{margin:4px 0}.row-actions{display:flex;align-items:center;gap:12px;flex-wrap:wrap}.error{color:#aa2836}.stock-search{padding-bottom:22px}.remove-confirm{padding:16px;border:1px solid #e0b7bc;border-radius:8px}.remove-confirm button{margin-right:12px}button,input{font:inherit;min-height:44px;padding:8px 14px;border:1px solid var(--border);border-radius:8px;background:white;color:var(--ink)}button{cursor:pointer}button:disabled{opacity:.5;cursor:not-allowed}.recovery{border-color:#d5b566}.recovery button{margin:0 12px 8px 0}@media(max-width:760px){.portfolio-page{padding:24px 16px}.panel{padding:18px}.position-row{grid-template-columns:1fr 1fr}.row-actions{grid-column:1/-1}}@media(max-width:420px){.position-row{grid-template-columns:1fr}}</style>
